#include <bits/stdc++.h>
using namespace std;
using ll = long long;

bool Mbe;
constexpr int N = 2e5 + 5;
constexpr int mod = 998244353;
void add(int &x, int y) {
  x += y, x >= mod && (x -= mod);
}

vector<int> e[N], g[N], son[N];
int node, dn, dfn[N], low[N], stc[N], top;
void tarjan(int id) {
  dfn[id] = low[id] = ++dn;
  stc[++top] = id;
  for(int it : e[id]) {
    if(!dfn[it]) {
      tarjan(it);
      low[id] = min(low[id], low[it]);
      if(low[it] >= dfn[id]) {
        g[++node].push_back(id);
        g[id].push_back(node);
        for(int x = 0; x != it; ) {
          g[node].push_back(x = stc[top--]);
          g[x].push_back(node);
        }
      }
    }
    else low[id] = min(low[id], dfn[it]);
  }
}

int n, m, k;
int R, sz[N], mx[N];
void dfs(int id, int ff) {
  sz[id] = id <= n;
  for(int it : g[id]) {
    if(it == ff) continue;
    dfs(it, id), sz[id] += sz[it];
    mx[id] = max(mx[id], sz[it]);
  }
  mx[id] = max(mx[id], n - sz[id]);
  if(mx[id] < mx[R]) R = id;
}

int ss[N];
unordered_map<int, int> f[N];
int calc() {
  int ans = 0;
  for(auto it : f[R]) {
    if(it.first * 2 <= n) add(ans, it.second);
  }
  return ans;
}
void merge(int x, int y) {
  unordered_map<int, int> nw;
  for(auto it : f[x]) {
    auto pt = f[y].find(it.first);
    if(pt != f[y].end()) nw[it.first] = 1ll * it.second * pt->second % mod;
  }
  f[x] = nw;
}

void dfs0(int id, int ff) {
  for(int it : g[id]) {
    if(it == ff) continue;
    dfs0(it, id), son[id].push_back(it);
  }
  sort(son[id].begin(), son[id].end(), [&](int x, int y) {
    return sz[x] < sz[y];
  });
  int E = son[id].size();
  if(id <= n) {
    for(int i = 1; i <= E; i++) ss[i] = ss[i - 1] + sz[son[id][i - 1]];
    auto update = [&](int x) {
      for(int i = E; i; i--) {
        int it = son[id][i - 1];
        if(sz[it] >= x) {
          auto pt = f[it].find(x);
          if(pt == f[it].end()) return;
          continue;
        }
        if(ss[i] + 1 != x) return;
        break;
      }
      f[id][x] = 1;
    };
    for(int i = 0; i <= E; i++) update(ss[i] + 1);
  }
  else {
    f[id] = f[son[id][0]];
    for(int i = 1; i < E; i++) merge(id, son[id][i]);
  }
}
void dfs1(int id, int ff) {
  for(int it : g[id]) {
    if(it == ff) continue;
    dfs1(it, id);
  }
  int E = son[id].size();
  if(id <= n) {
    for(int i = 1; i <= E; i++) ss[i] = ss[i - 1] + sz[son[id][i - 1]];
    auto update = [&](int x) {
      int prod = 1, size = 1, cnt = 0;
      for(int i = E; i && size <= x + 1; i--) {
        int it = son[id][i - 1];
        if(sz[it] >= x) {
          auto pt = f[it].find(x);
          if(sz[it] >= x + 1) {
            if(pt == f[it].end()) return;
            prod = 1ll * prod * pt->second % mod;
          }
          else {
            if(pt == f[it].end()) size += sz[it];
            else cnt++;
          }
        }
        else {
          size += ss[i];
          break;
        }
      }
      if(size > x + 1) return;
      f[id][x] = 1ll * prod * ((int) (size >= x) + (size == 1 ? cnt : 0)) % mod;
    };
    for(int i = 0; i <= E; i++) {
      if(i && ss[i - 1] + 1 != ss[i]) update(ss[i]);
      update(ss[i] + 1);
    }
  }
  else {
    f[id] = f[son[id][0]];
    for(int i = 1; i < E; i++) merge(id, son[id][i]);
  }
}

